/* deleteOrganization - Lee Ji Seob */
UPDATE SAA000 /* 통합기관 */
SET DEL_YN = 'Y', LAST_MDFR_ID = #{userId}, LAST_MDFCN_DT = SYSDATE
WHERE INST_NO = #{instNo}


/* updateCnterPreconOperHour - Lee.Tae.Ho */

UPDATE AKA510 /* 센터현황-운영시간 */
   SET DAOFTH_SE_CD     = #{DAOFTH_SE_CD},
       WORK_HR_OPSY_YN  = #{WORK_HR_OPSY_YN},
       WORK_BGNG_HR     = #{WORK_BGNG_HR},
       WORK_END_HR      = #{WORK_END_HR},               
       LAST_MDFR_ID     = #{USER_ID},
       LAST_MDFCN_DT    = SYSDATE
 WHERE INST_NO          = #{INST_NO}
   AND INDEX_SN         = #{INDEX_SN}


/* updateCnterPreconTelephone1388 - Lee.Tae.Ho */

