    , #{INST_NM}
    , #{UP_INST_NO}
    , #{UP_APRV_INST_NO}
    , #{CTPV_CD}
    , #{SGG_CD}
    , C##RG.ENC_B64(#{RPRSV_NM_ENCPT})
